// All public-site CSS, one string, injected by <Chrome>. Colours and fonts come
// from the brand custom properties (templates/brand), never hardcoded here.

const css = `
.sbs{background:var(--kr-background);color:var(--kr-text);font-family:var(--kr-font-body);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
.sbs *,.sbs *::before,.sbs *::after{box-sizing:border-box}
.sbs img{max-width:100%;display:block}
.sbs a{color:inherit;text-decoration:none}
.sbs-wrap{width:min(1240px,100% - 48px);margin-inline:auto}
.sbs-section{padding:clamp(72px,10vw,140px) 0}
.sbs-alt{background:var(--kr-background-alt)}

/* titles: big, light, tight (the reference style) */
.sbs-eyebrow{display:block;margin:0 0 18px;font-size:15px;font-weight:400;color:var(--kr-text-muted)}
.sbs-title{margin:0;font-family:var(--kr-font-heading);font-weight:500;font-size:clamp(2.4rem,5.4vw,4.6rem);line-height:1.06;letter-spacing:-.035em;color:var(--kr-primary)}
.sbs-title--md{font-size:clamp(1.9rem,3.6vw,3rem)}
.sbs-lede{margin:22px 0 0;max-width:34em;font-size:17px;color:var(--kr-text-muted)}
.sbs-card-title{margin:0;font-family:var(--kr-font-heading);font-weight:500;font-size:1.45rem;line-height:1.25;letter-spacing:-.02em;color:var(--kr-primary)}
.sbs-on-dark .sbs-title,.sbs-on-dark .sbs-card-title{color:#fff}
.sbs-on-dark .sbs-eyebrow,.sbs-on-dark .sbs-lede{color:rgba(255,255,255,.68)}

/* buttons: dark, square-ish, with an arrow */
.sbs-btn{display:inline-flex;align-items:center;gap:10px;padding:15px 24px;border:1px solid var(--kr-primary);background:var(--kr-primary);color:#fff!important;font:500 15px/1 var(--kr-font-body);border-radius:3px;cursor:pointer;transition:background .25s,border-color .25s,color .25s}
.sbs-btn:hover{background:var(--kr-accent);border-color:var(--kr-accent);color:var(--kr-primary)!important}
.sbs-btn--ghost{background:transparent;color:var(--kr-primary)!important}
.sbs-btn--gold{background:var(--kr-accent);border-color:var(--kr-accent);color:var(--kr-primary)!important}
.sbs-btn--gold:hover{background:var(--kr-accent-light);border-color:var(--kr-accent-light)}
.sbs-on-dark .sbs-btn--ghost{color:#fff!important;border-color:rgba(255,255,255,.5)}
.sbs-on-dark .sbs-btn--ghost:hover{background:#fff;color:var(--kr-primary)!important}

/* header */
.sbs-header{position:sticky;top:0;z-index:50;background:rgba(250,247,242,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--kr-border)}
.sbs-header__bar{display:flex;align-items:center;justify-content:space-between;height:78px;gap:24px}
.sbs-mark{font-family:var(--kr-font-brand);font-weight:600;font-size:1.25rem;letter-spacing:.14em;color:var(--kr-primary)}
.sbs-mark small{display:block;margin-top:3px;font:400 10.5px/1 var(--kr-font-body);letter-spacing:.3em;color:var(--kr-accent-dark)}
.sbs-nav{display:flex;align-items:center;gap:34px}
.sbs-nav a:not(.sbs-btn){font-size:15px;font-weight:500;color:var(--kr-primary);position:relative;padding:6px 0}
.sbs-nav a:not(.sbs-btn)::after{content:"";position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--kr-accent);transform:scaleX(0);transform-origin:left;transition:transform .3s}
.sbs-nav a:not(.sbs-btn):hover::after{transform:scaleX(1)}
.sbs-burger{display:none;background:none;border:0;padding:8px;color:var(--kr-primary);cursor:pointer}
@media(max-width:960px){
 .sbs-burger{display:block}
 .sbs-nav{position:absolute;inset:78px 0 auto 0;flex-direction:column;align-items:flex-start;gap:0;background:var(--kr-background);border-bottom:1px solid var(--kr-border);padding:8px 24px 24px;display:none}
 .sbs-nav.is-open{display:flex}
 .sbs-nav a:not(.sbs-btn){padding:14px 0;width:100%;font-size:18px}
 .sbs-nav .sbs-btn{margin-top:12px}
}

/* stats */
.sbs-stats{background:var(--kr-primary);color:#fff}
.sbs-stats__grid{display:grid;grid-template-columns:repeat(4,1fr)}
.sbs-stat{padding:44px 28px;border-left:1px solid rgba(255,255,255,.16)}
.sbs-stat:first-child{border-left:0}
.sbs-stat b{display:block;font:500 clamp(2rem,3.6vw,3rem)/1 var(--kr-font-heading);letter-spacing:-.03em;color:var(--kr-accent-light)}
.sbs-stat span{display:block;margin-top:10px;font-size:15px;color:rgba(255,255,255,.7)}
@media(max-width:760px){.sbs-stats__grid{grid-template-columns:1fr 1fr}.sbs-stat:nth-child(3){border-left:0}.sbs-stat{padding:28px 20px;border-top:1px solid rgba(255,255,255,.16)}.sbs-stat:nth-child(-n+2){border-top:0}}

/* about */
.sbs-about{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(32px,7vw,110px);align-items:start}
.sbs-about p{margin:0 0 18px;color:var(--kr-text-muted)}
.sbs-quote{margin:0;padding:clamp(28px,4vw,48px);background:var(--kr-primary);color:#fff;border-radius:3px}
.sbs-quote p{margin:0;font:500 clamp(1.4rem,2.4vw,2rem)/1.3 var(--kr-font-heading);letter-spacing:-.025em;color:#fff}
.sbs-quote cite{display:block;margin-top:22px;font:400 14px/1 var(--kr-font-body);font-style:normal;color:var(--kr-accent-light)}
@media(max-width:860px){.sbs-about{grid-template-columns:1fr}}

/* services: copied from the Adina template's service strip (ServiceAreaOne) */
.sbs-svchead{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,5vw,80px);align-items:end;padding-bottom:clamp(40px,5vw,64px)}
.sbs-svchead p{margin:0;max-width:30em;color:var(--kr-text-muted)}
@media(max-width:860px){.sbs-svchead{grid-template-columns:1fr}}
.sbs-svc{position:relative;overflow:hidden;background:var(--kr-primary-dark);color:#fff}
.sbs-svc__bg{position:absolute;inset:0;background:var(--kr-primary-dark)}
.sbs-svc__img{position:absolute;inset:0;background-position:center;background-size:cover;background-repeat:no-repeat;visibility:hidden;opacity:0;transform:scale(1.025);transition:all 1s cubic-bezier(.23,1,.32,1)}
.sbs-svc__img::after{content:"";position:absolute;inset:0;background:rgba(22,35,58,.5)}
.sbs-svc__img.is-on{visibility:visible;opacity:1;transform:scale(1)}
.sbs-svc__cols{position:relative;display:grid;grid-template-columns:repeat(5,1fr)}
.sbs-svc__col{position:relative;display:block;border-right:1px solid rgba(255,255,255,.1);overflow:hidden}
.sbs-svc__col::before{content:"";position:absolute;right:0;bottom:0;width:1px;height:0;background:#fff;transition:all .4s ease}
.sbs-svc__col:hover::before,.sbs-svc__col:focus-within::before{height:100%;bottom:auto;top:0}
.sbs-svc__wrap{position:relative;padding:25px 40px 50px;min-height:clamp(600px,44vw,700px);display:flex;flex-direction:column}
.sbs-svc__tag{position:absolute;right:16px;top:50px;padding:11px 6px;writing-mode:vertical-rl;font:700 14px/1 var(--kr-font-body);color:#fff;background:rgba(255,255,255,.1);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
.sbs-svc__num{margin:0;font:700 150px/100% var(--kr-font-heading);color:transparent;-webkit-text-stroke:1px rgba(249,246,246,.35);transform:translateY(-60px);opacity:0;visibility:hidden;transition:all .4s ease}
.sbs-svc__content{margin-top:auto;transform:translateY(142px);transition:all .4s ease}
.sbs-svc__title{margin:0;font:500 32px/131% var(--kr-font-heading);letter-spacing:-.02em;color:#fff}
.sbs-svc__title a{background-image:linear-gradient(#fff,#fff);background-size:0 1px;background-position:0 100%;background-repeat:no-repeat;transition:all .3s ease}
.sbs-svc__title a:hover{background-size:100% 1px}
.sbs-svc__inner{opacity:0;visibility:hidden;transition:all .4s ease}
.sbs-svc__para{margin:14px 0 45px;min-height:6em;font-size:16px;line-height:150%;color:rgba(255,255,255,.7)}
.sbs-svc__btn{display:inline-flex;align-items:center;gap:10px;padding:19px 24px;background:#fff;color:var(--kr-primary)!important;font:600 14px/100% var(--kr-font-body)}
.sbs-svc__btn svg{overflow:hidden;fill:currentColor}
.sbs-svc__btn path{transition:transform .35s ease,opacity .35s ease}
.sbs-svc__btn path:nth-of-type(2){transform:translate(-10px,10px);opacity:.5}
.sbs-svc__btn:hover path:nth-of-type(1){transform:translate(10px,-10px);opacity:0}
.sbs-svc__btn:hover path:nth-of-type(2){transform:translate(0,0);opacity:1}
.sbs-svc__col:hover .sbs-svc__content,.sbs-svc__col:focus-within .sbs-svc__content{transform:translateY(0)}
.sbs-svc__col:hover .sbs-svc__inner,.sbs-svc__col:focus-within .sbs-svc__inner{opacity:1;visibility:visible}
.sbs-svc__col:hover .sbs-svc__num,.sbs-svc__col:focus-within .sbs-svc__num{transform:translateY(0);opacity:1;visibility:visible}
.sbs-svc__thumb{display:none}
@media(max-width:1599px){.sbs-svc__title{font-size:22px}}
@media(max-width:1399px){.sbs-svc__wrap{padding:25px 20px 50px}.sbs-svc__num{font-size:80px}}
/* below the desktop strip there is no hover, so every column shows its text and own picture */
@media(max-width:1199px){
 .sbs-svc__bg{display:none}
 .sbs-svc__cols{grid-template-columns:1fr 1fr}
 .sbs-svc__col:last-child:nth-child(odd){grid-column:1/-1}
 .sbs-svc__col{border-bottom:1px solid rgba(255,255,255,.1);isolation:isolate}
 .sbs-svc__thumb{display:block;position:absolute;inset:0;z-index:-1;background-size:cover;background-position:center}
 .sbs-svc__thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(22,35,58,.35),rgba(22,35,58,.85))}
 .sbs-svc__wrap{min-height:340px;padding:25px 24px 32px}
 .sbs-svc__num{display:none}
 .sbs-svc__content,.sbs-svc__col:hover .sbs-svc__content{transform:none}
 .sbs-svc__inner{opacity:1;visibility:visible}
 .sbs-svc__para{margin:10px 0 24px;min-height:0}
 .sbs-svc__title{font-size:26px}
}
@media(max-width:700px){.sbs-svc__cols{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.sbs-svc__img,.sbs-svc__content,.sbs-svc__inner,.sbs-svc__num{transition:none}}

/* listings */
.sbs-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin-top:56px}
@media(max-width:960px){.sbs-grid{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.sbs-grid{grid-template-columns:1fr}}
.sbs-listing{display:flex;flex-direction:column;background:#fff;border:1px solid var(--kr-border);border-radius:3px;overflow:hidden;transition:transform .35s,box-shadow .35s}
.sbs-listing:hover{transform:translateY(-4px);box-shadow:0 22px 50px rgba(22,35,58,.14)}
.sbs-listing__img{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--kr-background-alt)}
.sbs-listing__img img{width:100%;height:100%;object-fit:cover;transition:transform .8s}
.sbs-listing:hover .sbs-listing__img img{transform:scale(1.05)}
.sbs-chip{position:absolute;left:14px;top:14px;padding:6px 12px;background:var(--kr-primary);color:#fff;font-size:12.5px;font-weight:500;border-radius:2px}
.sbs-chip--gold{background:var(--kr-accent);color:var(--kr-primary)}
.sbs-chip--sample{left:auto;right:14px;background:rgba(255,255,255,.92);color:var(--kr-primary)}
.sbs-listing__body{padding:24px 24px 26px}
.sbs-price{margin:0 0 6px;font:500 1.7rem/1.1 var(--kr-font-heading);letter-spacing:-.03em;color:var(--kr-primary)}
.sbs-listing__loc{margin:6px 0 0;font-size:15px;color:var(--kr-text-muted)}
.sbs-facts{display:flex;flex-wrap:wrap;gap:6px 18px;margin:18px 0 0;padding:16px 0 0;border-top:1px solid var(--kr-border);list-style:none;font-size:14.5px;color:var(--kr-text-muted)}
.sbs-facts b{font-weight:500;color:var(--kr-primary)}
.sbs-head-row{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:24px}

/* communities */
.sbs-towns{display:flex;flex-wrap:wrap;gap:0 40px;margin:44px 0 0;padding:0;list-style:none}
.sbs-towns a{display:inline-block;padding:10px 0;font:500 clamp(1.9rem,4.6vw,3.8rem)/1.1 var(--kr-font-heading);letter-spacing:-.035em;color:var(--kr-primary);opacity:.4;transition:opacity .3s}
.sbs-towns a:hover{opacity:1}

/* instagram */
.sbs-ig{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:48px}
.sbs-ig a{position:relative;aspect-ratio:1;overflow:hidden;border-radius:3px;display:block}
.sbs-ig img{width:100%;height:100%;object-fit:cover;transition:transform .7s}
.sbs-ig a:hover img{transform:scale(1.07)}
@media(max-width:760px){.sbs-ig{grid-template-columns:1fr 1fr}}

/* contact band */
.sbs-contact{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(32px,7vw,110px);align-items:start}
.sbs-details{margin:36px 0 0;padding:0;list-style:none}
.sbs-details li{padding:16px 0;border-top:1px solid rgba(255,255,255,.16);font-size:16px;color:rgba(255,255,255,.88)}
.sbs-details small{display:block;font-size:13px;color:var(--kr-accent-light);margin-bottom:2px}
.sbs-formcard{padding:clamp(24px,3.4vw,44px);background:var(--kr-background);color:var(--kr-text);border-radius:3px}
@media(max-width:860px){.sbs-contact{grid-template-columns:1fr}}

/* footer */
.sbs-footer{background:var(--kr-primary-dark);color:rgba(255,255,255,.72);padding:72px 0 36px;font-size:15px}
.sbs-footer .sbs-mark{color:#fff}
.sbs-footer__grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:48px}
.sbs-footer h4{margin:0 0 16px;font:500 14px/1 var(--kr-font-body);color:var(--kr-accent-light)}
.sbs-footer ul{margin:0;padding:0;list-style:none}
.sbs-footer li{padding:5px 0}
.sbs-footer a:hover{color:#fff}
.sbs-legal{margin-top:56px;padding-top:28px;border-top:1px solid rgba(255,255,255,.14);font-size:13px;line-height:1.7;color:rgba(255,255,255,.5)}
@media(max-width:760px){.sbs-footer__grid{grid-template-columns:1fr}}

/* inner pages */
.sbs-pagehead{padding:clamp(56px,8vw,110px) 0 clamp(32px,4vw,56px);border-bottom:1px solid var(--kr-border)}
.sbs-filters{display:flex;flex-wrap:wrap;gap:12px;margin-top:40px}
.sbs-filters input,.sbs-filters select{height:50px;padding:0 16px;border:1px solid var(--kr-border);background:#fff;border-radius:3px;font:400 15px var(--kr-font-body);color:var(--kr-text)}
.sbs-filters input{flex:1 1 240px}
.sbs-empty{padding:72px 0;text-align:center;color:var(--kr-text-muted)}
.sbs-detail{display:grid;grid-template-columns:1.5fr 1fr;gap:clamp(28px,5vw,72px);align-items:start;margin-top:48px}
.sbs-detail__hero{aspect-ratio:16/10;border-radius:3px;overflow:hidden;background:var(--kr-background-alt)}
.sbs-detail__hero img{width:100%;height:100%;object-fit:cover}
.sbs-thumbs{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:10px}
.sbs-thumbs button{padding:0;border:2px solid transparent;border-radius:3px;overflow:hidden;aspect-ratio:4/3;cursor:pointer;background:none}
.sbs-thumbs button.is-active{border-color:var(--kr-accent)}
.sbs-thumbs img{width:100%;height:100%;object-fit:cover}
.sbs-amen{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0 0;padding:0;list-style:none}
.sbs-amen li{padding:8px 16px;border:1px solid var(--kr-border);background:#fff;border-radius:99px;font-size:14.5px}
.sbs-side{position:sticky;top:104px;padding:32px;background:#fff;border:1px solid var(--kr-border);border-radius:3px}
@media(max-width:960px){.sbs-detail{grid-template-columns:1fr}.sbs-side{position:static}}
.sbs-prose p{margin:0 0 18px;color:var(--kr-text-muted)}
`;

export default css;
