import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { LuArrowUpRight, LuHouse, LuInstagram, LuMenu, LuX } from "react-icons/lu";

import {
  AGENT_NAME,
  BROKERAGE,
  BUSINESS_NAME,
} from "../ppm/config/profile--business-name";
import {
  EMAIL,
  EMAIL_HREF,
  INSTAGRAM_URL,
  LOCATION,
  PHONE_DISPLAY,
  PHONE_HREF,
} from "../ppm/config/profile--contact";
import { COMMUNITIES, NAV } from "./content";
import css from "./styles";
import pagesCss from "./stylesPages";

/** The dark arrow button used everywhere. `to` is internal; `href` is external. */
export function Btn({
  to,
  href,
  variant,
  children,
}: {
  to?: string;
  href?: string;
  variant?: "ghost" | "gold";
  children: React.ReactNode;
}) {
  const className = `sbs-btn${variant ? ` sbs-btn--${variant}` : ""}`;
  const inner = (
    <>
      {children}
      <LuArrowUpRight size={16} aria-hidden="true" />
    </>
  );
  return to ? (
    <Link to={to} className={className}>
      {inner}
    </Link>
  ) : (
    <a href={href} className={className} {...(href?.startsWith("http") ? { target: "_blank", rel: "noreferrer" } : {})}>
      {inner}
    </a>
  );
}

/** Small quiet eyebrow, then the large light title. */
export function SectionHead({
  eyebrow,
  title,
  lede,
  medium,
}: {
  eyebrow: string;
  title: React.ReactNode;
  lede?: string;
  medium?: boolean;
}) {
  return (
    <div>
      <span className="sbs-eyebrow">{eyebrow}</span>
      <h2 className={`sbs-title${medium ? " sbs-title--md" : ""}`}>{title}</h2>
      {lede ? <p className="sbs-lede">{lede}</p> : null}
    </div>
  );
}

function Wordmark() {
  return (
    <Link to="/" className="sbs-mark" aria-label={`${BUSINESS_NAME} home`}>
      SOLD BY SAJRA
      <small>BOISE · IDAHO</small>
    </Link>
  );
}

function Header({ overlay }: { overlay?: boolean }) {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    if (!overlay) return;
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [overlay]);

  const floating = overlay && !scrolled && !open;
  return (
    <header className={`sbs-header${overlay ? " sbs-header--fixed" : ""}${floating ? " is-overlay" : ""}`}>
      <div className="sbs-wrap sbs-header__bar">
        <Wordmark />
        <button
          type="button"
          className="sbs-burger"
          aria-label={open ? "Close menu" : "Open menu"}
          aria-expanded={open}
          onClick={() => setOpen((value) => !value)}
        >
          {open ? <LuX size={26} /> : <LuMenu size={26} />}
        </button>
        <nav className={`sbs-nav${open ? " is-open" : ""}`} aria-label="Main">
          {NAV.map((item) => (
            <Link key={item.label} to={item.to} onClick={() => setOpen(false)}>
              {item.label}
            </Link>
          ))}
          <Btn href={PHONE_HREF}>{PHONE_DISPLAY}</Btn>
        </nav>
      </div>
    </header>
  );
}

function Footer() {
  return (
    <footer className="sbs-footer">
      <div className="sbs-wrap">
        <div className="sbs-footer__grid">
          <div>
            <span className="sbs-mark">SOLD BY SAJRA</span>
            <p className="sbs-footer__blurb">
              {AGENT_NAME}, REALTOR®. Helping Treasure Valley families buy, sell and invest with honesty, hard work and
              a builder’s eye.
            </p>
            <a href={INSTAGRAM_URL} target="_blank" rel="noreferrer" aria-label="Instagram" className="sbs-footer__social">
              <LuInstagram size={20} />
            </a>
          </div>
          <div>
            <h4>Explore</h4>
            <ul>
              {NAV.map((item) => (
                <li key={item.label}>
                  <Link to={item.to}>{item.label}</Link>
                </li>
              ))}
              <li>
                <Link to="/apply/">Get started</Link>
              </li>
            </ul>
          </div>
          <div>
            <h4>Communities</h4>
            <ul className="sbs-footer__towns">
              {COMMUNITIES.map((town) => (
                <li key={town}>
                  <Link to={`/properties/?town=${encodeURIComponent(town)}`}>{town}</Link>
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h4>Get in touch</h4>
            <ul>
              <li>
                <a href={PHONE_HREF}>{PHONE_DISPLAY}</a>
              </li>
              <li>
                <a href={EMAIL_HREF}>{EMAIL}</a>
              </li>
              <li>{BROKERAGE}</li>
              <li>{LOCATION} · By appointment</li>
            </ul>
          </div>
        </div>

        <div className="sbs-legal">
          <div className="sbs-legal__row">
            <span className="sbs-legal__eho">
              <LuHouse size={18} aria-hidden="true" /> Equal Housing Opportunity
            </span>
            <span>
              <Link to="/privacy/">Privacy</Link> · <Link to="/terms/">Terms</Link>
            </span>
            <a href="#top" className="sbs-legal__top" onClick={(e) => (e.preventDefault(), window.scrollTo({ top: 0, behavior: "smooth" }))}>
              Back to top ↑
            </a>
          </div>
          <p>
            © {new Date().getFullYear()} {AGENT_NAME} / {BROKERAGE}. Licensed in the State of Idaho. Information is
            deemed reliable but not guaranteed. This is not a solicitation for listings already under another broker’s
            agreement.
          </p>
        </div>
      </div>
    </footer>
  );
}

/** Header, footer and the page CSS. Every page, including the 404, sits inside it. */
export default function Chrome({ children, overlay }: { children: React.ReactNode; overlay?: boolean }) {
  return (
    <div className="sbs">
      <style>{css + pagesCss}</style>
      <Header overlay={overlay} />
      <main>{children}</main>
      <Footer />
    </div>
  );
}

export { Wordmark };
