// CSS for the listings search page and the listing detail page. Injected with
// styles.ts by <Chrome>; same brand custom properties, same sbs- prefix.

const css = `
/* listing search page */
.sbs-search{display:flex;align-items:center;gap:12px;margin-top:36px;max-width:640px;height:58px;padding:0 20px;background:#fff;border:1px solid var(--kr-border);border-radius:3px;color:var(--kr-text-muted)}
.sbs-search input{flex:1;border:0;outline:0;background:none;font:400 16px var(--kr-font-body);color:var(--kr-text)}
.sbs-lst{display:grid;grid-template-columns:290px 1fr;gap:clamp(24px,4vw,56px);align-items:start}
.sbs-side-filters{position:sticky;top:100px;padding:26px;background:#fff;border:1px solid var(--kr-border);border-radius:3px;max-height:calc(100vh - 120px);overflow:auto}
.sbs-side-filters__head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:6px}
.sbs-side-filters__close,.sbs-side-filters__apply{display:none}
.sbs-side-filters fieldset{margin:0;padding:0 0 20px;border:0;min-width:0}
.sbs-side-filters legend{float:left;width:100%;padding:20px 0 12px;border-top:1px solid var(--kr-border);font:600 15px var(--kr-font-body);color:var(--kr-primary)}
.sbs-side-filters legend+*{clear:both}
.sbs-check{display:flex;align-items:center;gap:10px;padding:5px 0;font-size:15px;cursor:pointer}
.sbs-check input{width:17px;height:17px;accent-color:var(--kr-primary)}
.sbs-check em{margin-left:auto;font-style:normal;font-size:13px;color:var(--kr-text-muted)}
.sbs-pills{display:flex;flex-wrap:wrap;gap:8px}
.sbs-pills button{min-width:46px;height:40px;padding:0 12px;border:1px solid var(--kr-border);background:#fff;border-radius:3px;font:500 14px var(--kr-font-body);cursor:pointer;color:var(--kr-text)}
.sbs-pills button.is-on{background:var(--kr-primary);border-color:var(--kr-primary);color:#fff}
.sbs-range{display:flex;align-items:center;gap:10px}
.sbs-range select{flex:1;min-width:0;height:44px;padding:0 10px;border:1px solid var(--kr-border);border-radius:3px;background:#fff;font:400 14.5px var(--kr-font-body)}
.sbs-link{background:none;border:0;padding:0;font:500 14px var(--kr-font-body);color:var(--kr-accent-dark);cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.sbs-toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding-bottom:20px}
.sbs-toolbar p{margin:0 auto 0 0;font-size:16px;color:var(--kr-text-muted)}
.sbs-toolbar select{height:46px;padding:0 14px;border:1px solid var(--kr-border);border-radius:3px;background:#fff;font:400 15px var(--kr-font-body)}
.sbs-toolbar__filters{display:none;padding:13px 18px}
.sbs-viewtoggle{display:flex;border:1px solid var(--kr-border);border-radius:3px;overflow:hidden;background:#fff}
.sbs-viewtoggle button{width:46px;height:44px;border:0;background:none;cursor:pointer;color:var(--kr-text-muted);display:grid;place-items:center}
.sbs-viewtoggle button.is-on{background:var(--kr-primary);color:#fff}
.sbs-chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:24px}
.sbs-chips button:not(.sbs-link){display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border:1px solid var(--kr-border);background:#fff;border-radius:99px;font:400 14px var(--kr-font-body);cursor:pointer}
.sbs-grid--2{grid-template-columns:repeat(2,1fr);margin-top:0}
.sbs-list{display:grid;gap:20px}
.sbs-listing--wide{flex-direction:row}
.sbs-listing--wide .sbs-listing__img{flex:0 0 38%;aspect-ratio:auto;min-height:230px}
.sbs-listing--wide .sbs-listing__body{flex:1}
.sbs-listing__sum{margin:12px 0 0;font-size:15px;color:var(--kr-text-muted)}
.sbs-facts li{display:flex;align-items:center;gap:6px}
.sbs-facts svg{color:var(--kr-accent-dark)}
@media(max-width:960px){
 .sbs-lst{grid-template-columns:1fr}
 .sbs-toolbar__filters{display:inline-flex}
 .sbs-side-filters{position:fixed;inset:0 auto 0 0;z-index:80;width:min(360px,92vw);max-height:none;border-radius:0;transform:translateX(-102%);transition:transform .3s}
 .sbs-side-filters.is-open{transform:none}
 .sbs-side-filters__close{display:block;background:none;border:0;cursor:pointer;color:var(--kr-primary)}
 .sbs-side-filters__apply{display:inline-flex;margin-top:12px;width:100%;justify-content:center}
 .sbs-scrim{position:fixed;inset:0;z-index:79;background:rgba(14,24,40,.5)}
}
@media(max-width:620px){.sbs-grid--2{grid-template-columns:1fr}.sbs-listing--wide{flex-direction:column}.sbs-listing--wide .sbs-listing__img{aspect-ratio:4/3;min-height:0}}

/* listing detail page */
.sbs-dhero{position:relative;min-height:clamp(420px,52vw,620px);display:flex;color:#fff;overflow:hidden;background:var(--kr-primary-dark)}
.sbs-dhero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.sbs-dhero__shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(14,24,40,.5) 0%,rgba(14,24,40,.12) 38%,rgba(14,24,40,.85) 100%)}
.sbs-dhero__inner{position:relative;display:flex;flex-direction:column;justify-content:space-between;padding-block:28px 44px}
.sbs-dhero__back{font-size:15px;font-weight:500;color:#fff;opacity:.9}
.sbs-dhero__row{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:28px}
.sbs-dhero .sbs-title{color:#fff;margin-top:16px}
.sbs-dhero__chips{display:flex;gap:8px}
.sbs-dhero__chips .sbs-chip{position:static}
.sbs-dhero__loc{display:flex;align-items:center;gap:8px;margin:14px 0 0;font-size:17px;color:rgba(255,255,255,.85)}
.sbs-dhero__aside{text-align:right}
.sbs-dhero__price{margin:0 0 16px;font:500 clamp(2rem,4vw,3rem)/1 var(--kr-font-heading);letter-spacing:-.03em}
.sbs-factbar{background:var(--kr-primary);color:#fff}
.sbs-factbar__grid{display:grid;grid-template-columns:repeat(5,1fr)}
.sbs-factbar__grid>div{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:26px 24px;border-left:1px solid rgba(255,255,255,.14)}
.sbs-factbar__grid>div:first-child{border-left:0;padding-left:0}
.sbs-factbar svg{color:var(--kr-accent-light);margin-bottom:6px}
.sbs-factbar b{font:500 1.4rem/1.1 var(--kr-font-heading);letter-spacing:-.02em}
.sbs-factbar span{font-size:14px;color:rgba(255,255,255,.65)}
@media(max-width:860px){.sbs-factbar__grid{grid-template-columns:repeat(3,1fr)}.sbs-factbar__grid>div{padding:20px 16px;border-top:1px solid rgba(255,255,255,.14)}.sbs-factbar__grid>div:nth-child(-n+3){border-top:0}.sbs-factbar__grid>div:nth-child(4){border-left:0;padding-left:0}}
.sbs-gtabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}
.sbs-gtabs button{padding:9px 18px;border:1px solid var(--kr-border);background:#fff;border-radius:99px;font:500 14.5px var(--kr-font-body);cursor:pointer;color:var(--kr-text)}
.sbs-gtabs button.is-on{background:var(--kr-primary);border-color:var(--kr-primary);color:#fff}
.sbs-gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.sbs-gallery button{position:relative;padding:0;border:0;aspect-ratio:4/3;overflow:hidden;border-radius:3px;cursor:zoom-in;background:var(--kr-background-alt)}
.sbs-gallery button:first-child{grid-column:span 2;grid-row:span 2;aspect-ratio:auto}
.sbs-gallery img{width:100%;height:100%;object-fit:cover;transition:transform .6s}
.sbs-gallery button:hover img{transform:scale(1.05)}
.sbs-gallery span{position:absolute;left:10px;bottom:10px;padding:4px 10px;background:rgba(14,24,40,.72);color:#fff;font-size:12.5px;border-radius:2px;opacity:0;transition:opacity .3s}
.sbs-gallery button:hover span{opacity:1}
.sbs-amen li{display:flex;align-items:center;gap:8px}
.sbs-amen svg{color:var(--kr-accent-dark)}
.sbs-dl{margin:18px 0 0;display:grid;grid-template-columns:1fr 1fr;gap:0 40px}
.sbs-dl>div{display:flex;justify-content:space-between;gap:16px;padding:14px 0;border-bottom:1px solid var(--kr-border)}
.sbs-dl dt{color:var(--kr-text-muted)}
.sbs-dl dd{margin:0;font-weight:500;color:var(--kr-primary);text-align:right}
@media(max-width:620px){.sbs-dl{grid-template-columns:1fr}.sbs-gallery{grid-template-columns:1fr 1fr}}
.sbs-agent{display:flex;align-items:center;gap:14px;margin-top:20px;padding-top:20px;border-top:1px solid var(--kr-border)}
.sbs-agent img{width:56px;height:56px;border-radius:50%;object-fit:cover;object-position:top;background:var(--kr-primary)}
.sbs-agent b{display:block;font-weight:600;color:var(--kr-primary)}
.sbs-agent span{font-size:14px;color:var(--kr-text-muted)}
.sbs-side__call{display:flex;align-items:center;justify-content:center;gap:8px;margin-top:18px;font-weight:500;color:var(--kr-primary)}
.sbs-lightbox{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;background:rgba(10,16,28,.94);padding:24px}
.sbs-lightbox figure{margin:0;max-width:min(1200px,86vw);max-height:90vh;text-align:center;color:#fff}
.sbs-lightbox img{max-width:100%;max-height:80vh;object-fit:contain;margin:0 auto;border-radius:3px}
.sbs-lightbox figcaption{margin-top:14px;font-size:15px;color:rgba(255,255,255,.75)}
.sbs-lightbox__close,.sbs-lightbox__nav{position:absolute;border:0;background:rgba(255,255,255,.12);color:#fff;border-radius:50%;width:52px;height:52px;display:grid;place-items:center;cursor:pointer;transition:background .2s}
.sbs-lightbox__close:hover,.sbs-lightbox__nav:hover{background:var(--kr-accent);color:var(--kr-primary)}
.sbs-lightbox__close{top:20px;right:20px}
.sbs-lightbox__nav{top:50%;transform:translateY(-50%)}
.sbs-lightbox__nav--prev{left:20px}
.sbs-lightbox__nav--next{right:20px}

/* contact section (the template's "Get in touch") */
.sbs-ct{background:var(--kr-background-alt);padding:clamp(80px,10vw,140px) 0 clamp(70px,8vw,110px)}
.sbs-ct__grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(32px,6vw,90px);align-items:center}
.sbs-ct__title{margin:0;font:500 clamp(2.2rem,4vw,3rem)/1.21 var(--kr-font-heading);letter-spacing:-.03em;color:var(--kr-primary)}
.sbs-ct__pre{margin:20px 0 55px;max-width:26em;line-height:1.5;color:var(--kr-primary)}
.sbs-ct__info{display:grid;grid-template-columns:1.4fr 1fr;gap:30px 24px}
.sbs-ct__info h4{margin:0 0 4px;font:500 20px/1.4 var(--kr-font-heading);letter-spacing:-.01em;color:var(--kr-primary)}
.sbs-ct__info a,.sbs-ct__info span{font-size:16px;line-height:1.62;color:var(--kr-text-muted);overflow-wrap:anywhere}
.sbs-ct__info a:hover{color:var(--kr-primary)}
.sbs-ct__social{display:inline-flex;margin-top:4px}
.sbs-ct__broker{margin:44px 0 0;font-size:14px;letter-spacing:.04em;color:var(--kr-accent-dark)}
.sbs-ct__card{background:#fff;padding:51px 45px 40px;box-shadow:0 30px 60px rgba(22,35,58,.08)}
.sbs-ct__formtitle{margin:0 0 40px;font:500 clamp(1.5rem,2.4vw,2rem)/1.31 var(--kr-font-heading);letter-spacing:-.025em;color:var(--kr-primary)}
.sbs-ct__formtitle span{color:rgba(22,35,58,.4)}
.sbs-ct__form input,.sbs-ct__form select,.sbs-ct__form textarea{display:block;width:100%;margin-bottom:10px;padding:13px 0;border:0;border-bottom:1px solid var(--kr-border);border-radius:0;background:none;outline:0;font:400 16px/1.5 var(--kr-font-body);color:var(--kr-text-muted);transition:border-color .3s}
.sbs-ct__form select{appearance:none;-webkit-appearance:none;cursor:pointer;background-image:linear-gradient(45deg,transparent 50%,var(--kr-text-muted) 50%),linear-gradient(135deg,var(--kr-text-muted) 50%,transparent 50%);background-position:calc(100% - 12px) 50%,calc(100% - 6px) 50%;background-size:6px 6px;background-repeat:no-repeat}
.sbs-ct__form textarea{height:150px;resize:none;margin-bottom:30px}
.sbs-ct__form input:focus,.sbs-ct__form select:focus,.sbs-ct__form textarea:focus{border-bottom-color:var(--kr-primary);color:var(--kr-text)}
.sbs-ct__form button{display:block;width:100%;padding:23px 20px;border:0;background:var(--kr-primary);color:#fff;font:700 14px/100% var(--kr-font-body);text-align:center;cursor:pointer;transition:background .4s}
.sbs-ct__form button:hover{background:var(--kr-primary-soft)}
.sbs-ct__form button:disabled{opacity:.6;cursor:wait}
.sbs-ct__error{margin:0 0 16px;font-size:14.5px;color:#b91c1c}
.sbs-ct__sent h4{margin:0 0 8px;font:500 1.5rem/1.2 var(--kr-font-heading);color:var(--kr-primary)}
.sbs-ct__sent p{margin:0 0 24px;color:var(--kr-text-muted)}
.sbs-ct__again{padding:0;border:0;background:none;font:500 15px var(--kr-font-body);color:var(--kr-accent-dark);cursor:pointer;text-decoration:underline;text-underline-offset:3px}
@media(max-width:900px){.sbs-ct__grid{grid-template-columns:1fr}}
@media(max-width:575px){.sbs-ct__card{padding:41px 20px 32px}.sbs-ct__info{grid-template-columns:1fr}}

/* case-studies card slider (the template's portfolio slider) */
.sbs-cs{overflow:hidden}
.sbs-cs__bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:20px;margin:48px 0 40px}
.sbs-cs__tabs{display:flex;flex-wrap:wrap;gap:0}
.sbs-cs__tabs button{margin:0 40px 0 0;padding:0;border:0;background:none;color:var(--kr-text-muted);font:400 16px/150% var(--kr-font-body);cursor:pointer;background-image:linear-gradient(var(--kr-primary),var(--kr-primary));background-size:0 1px;background-position:0 100%;background-repeat:no-repeat;transition:all .3s ease}
.sbs-cs__tabs button:hover,.sbs-cs__tabs button.is-on{background-size:100% 1px;color:var(--kr-primary)}
.sbs-cs__slider{margin-right:0}
@media(min-width:769px){.sbs-cs__slider{margin-right:calc((100% - 100vw) / 2)}}
.sbs-case{padding-bottom:6px}
.sbs-case__thumb{display:block;margin-bottom:30px;overflow:hidden;aspect-ratio:5/4;background:var(--kr-background-alt)}
.sbs-case__thumb img{width:100%;height:100%;object-fit:cover;transition:transform .8s ease}
.sbs-case:hover .sbs-case__thumb img{transform:scale(1.1)}
.sbs-case__tags{margin-bottom:20px}
.sbs-case__tags span{display:inline-block;margin:0 7px 10px 0;padding:9px 19px;border:1px solid var(--kr-border);border-radius:96px;font-size:14px;line-height:143%;color:var(--kr-primary)}
.sbs-case__title{margin:0;font:500 32px/131% var(--kr-font-heading);letter-spacing:-.025em;color:var(--kr-primary)}
@media(max-width:575px){.sbs-case__title{font-size:26px}}
.sbs-case__title a{background-image:linear-gradient(var(--kr-primary),var(--kr-primary));background-size:0 1px;background-position:0 100%;background-repeat:no-repeat;transition:all .3s ease}
.sbs-case__title a:hover{background-size:100% 1px}
.sbs-case__price{margin:10px 0 0;font:500 1.25rem/1.2 var(--kr-font-heading);letter-spacing:-.02em;color:var(--kr-accent-dark)}
.sbs-case .sbs-facts{border-top:0;padding-top:0;margin-top:12px}

/* header floating over the hero */
.sbs-header{transition:background .3s,border-color .3s}
.sbs-header.sbs-header--fixed{position:fixed;left:0;right:0;top:0}
.sbs-header.is-overlay{background:transparent;border-bottom-color:rgba(255,255,255,.16);backdrop-filter:none;-webkit-backdrop-filter:none}
.sbs-header.is-overlay .sbs-mark{color:#fff}
.sbs-header.is-overlay .sbs-mark small{color:var(--kr-accent-light)}
.sbs-header.is-overlay .sbs-nav a:not(.sbs-btn){color:#fff}
.sbs-header.is-overlay .sbs-btn{background:#fff;border-color:#fff;color:var(--kr-primary)!important}
.sbs-header.is-overlay .sbs-btn:hover{background:var(--kr-accent);border-color:var(--kr-accent)}
.sbs-header.is-overlay .sbs-burger{color:#fff}

/* hero: full-bleed home photo, headline, find-a-home panel */
.sbs-hero2{position:relative;display:flex;min-height:max(780px,100vh);color:#fff;overflow:hidden;background:var(--kr-primary-dark);isolation:isolate}
.sbs-hero2__bg{position:absolute;inset:0;z-index:-2;width:100%;height:100%;object-fit:cover;object-position:center 62%}
.sbs-hero2__shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(14,24,40,.72) 0%,rgba(14,24,40,.3) 30%,rgba(14,24,40,.4) 58%,rgba(14,24,40,.9) 100%),linear-gradient(90deg,rgba(14,24,40,.5) 0%,rgba(14,24,40,0) 62%)}
.sbs-hero2__inner{position:relative;width:min(1240px,100% - 48px);margin-inline:auto;display:grid;grid-template-columns:1fr auto;grid-template-rows:1fr auto;align-items:end;column-gap:32px;padding:150px 0 clamp(32px,4vw,56px)}
.sbs-hero2__copy{grid-column:1;max-width:800px;margin-bottom:clamp(36px,5vw,64px)}
.sbs-hero2__pill{display:inline-block;margin-bottom:26px;padding:9px 18px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.1);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);border-radius:99px;font-size:14px;letter-spacing:.02em}
.sbs-hero2 h1{margin:0;font:500 clamp(2.5rem,5.5vw,5.2rem)/1.04 var(--kr-font-heading);letter-spacing:-.04em;color:#fff}
.sbs-hero2__copy p{margin:24px 0 0;max-width:34em;font-size:18px;color:rgba(255,255,255,.86)}
.sbs-hero2__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}
.sbs-hero2 .sbs-btn--ghost{color:#fff!important;border-color:rgba(255,255,255,.55);background:transparent}
.sbs-hero2 .sbs-btn--ghost:hover{background:#fff;color:var(--kr-primary)!important}
.sbs-hero2__agent{grid-column:2;display:flex;align-items:center;gap:14px;margin-bottom:clamp(36px,5vw,64px);padding:12px 22px 12px 12px;border:1px solid rgba(255,255,255,.26);background:rgba(255,255,255,.12);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border-radius:99px;transition:background .3s}
.sbs-hero2__agent:hover{background:rgba(255,255,255,.2)}
.sbs-hero2__agent img{width:62px;height:62px;border-radius:50%;object-fit:cover;object-position:top;background:var(--kr-primary-soft)}
.sbs-hero2__agent b{display:block;font:600 16px/1.2 var(--kr-font-body)}
.sbs-hero2__agent small{display:block;font-size:13px;color:rgba(255,255,255,.75)}
.sbs-hero2__agent em{display:flex;align-items:center;gap:6px;margin-top:3px;font-style:normal;font-size:14px;font-weight:500;color:var(--kr-accent-light)}
.sbs-find{grid-column:1/-1;background:#fff;color:var(--kr-text);border-radius:4px;box-shadow:0 30px 80px rgba(8,14,26,.4)}
.sbs-find__tabs{display:flex;border-bottom:1px solid var(--kr-border)}
.sbs-find__tabs button{position:relative;padding:16px 34px;border:0;background:none;font:600 15px var(--kr-font-body);color:var(--kr-text-muted);cursor:pointer}
.sbs-find__tabs button.is-on{color:var(--kr-primary)}
.sbs-find__tabs button.is-on::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--kr-accent)}
.sbs-find__form{display:grid;grid-template-columns:1.2fr 1fr 1fr .8fr auto}
.sbs-find__form label{display:flex;flex-direction:column;gap:4px;padding:18px 24px;border-right:1px solid var(--kr-border);min-width:0}
.sbs-find__form label span{font-size:13px;color:var(--kr-text-muted)}
.sbs-find__form select{width:100%;padding:2px 0;border:0;outline:0;background:none;font:500 16px var(--kr-font-body);color:var(--kr-primary);cursor:pointer}
.sbs .sbs-find__go{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:68px;padding:0 38px;border:0;background:var(--kr-primary);color:#fff;font:600 15px var(--kr-font-body);cursor:pointer;transition:background .25s,color .25s}
.sbs .sbs-find__go:hover{background:var(--kr-accent);color:var(--kr-primary)}
.sbs-find__sell{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-left:28px}
.sbs-find__sell p{margin:0;padding:18px 0;color:var(--kr-text-muted)}
.sbs-find__sell p b{color:var(--kr-primary);font-weight:600}
@media(max-width:960px){
 .sbs-find__form{grid-template-columns:1fr 1fr}
 .sbs-find__form label{border-bottom:1px solid var(--kr-border)}
 .sbs-find__form label:nth-child(2){border-right:0}
 .sbs .sbs-find__go{grid-column:1/-1}
}
@media(max-width:860px){
 .sbs-hero2__inner{grid-template-columns:1fr}
 .sbs-hero2__agent{display:none}
}
@media(max-width:560px){
 .sbs-hero2{min-height:0}
 .sbs-hero2__inner{padding-top:120px}
 .sbs-find__form{grid-template-columns:1fr}
 .sbs-find__form label{border-right:0}
 .sbs-find__sell{flex-direction:column;align-items:stretch;padding:0}
 .sbs-find__sell p{padding:18px 20px 4px}
 .sbs-find__tabs button{flex:1;padding:16px 10px}
}

/* about: framed portrait + story */
.sbs-title--lg{font-size:clamp(2.2rem,4.2vw,3.5rem);line-height:1.08}
.sbs-ab{overflow:hidden}
.sbs-ab__grid{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(48px,8vw,120px);align-items:center}
.sbs-ab__art{position:relative;width:min(100%,470px);margin:0 auto;padding:0 28px 28px 0}
.sbs-ab__frame{position:absolute;inset:28px 0 0 28px;border:1.5px solid var(--kr-accent);border-radius:999px 999px 6px 6px;transition:transform 1s cubic-bezier(.23,1,.32,1) .5s}
.sbs-ab__photo{position:relative;aspect-ratio:4/5.3;overflow:hidden;border-radius:999px 999px 6px 6px;background:linear-gradient(170deg,var(--kr-primary-soft),var(--kr-primary-dark));box-shadow:0 40px 80px rgba(22,35,58,.28);transition:clip-path 1.3s cubic-bezier(.23,1,.32,1)}
.sbs-ab__photo::before{content:"";position:absolute;inset:14px;z-index:2;border:1px solid rgba(228,205,151,.55);border-radius:999px 999px 2px 2px;pointer-events:none}
.sbs-ab__photo::after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(22,35,58,0) 55%,rgba(22,35,58,.55) 100%);pointer-events:none}
.sbs-ab__photo img{width:100%;height:100%;object-fit:cover;object-position:56% 18%;filter:grayscale(1) contrast(1.06) brightness(1.02);transform:scale(1.02);transition:transform 1.6s cubic-bezier(.23,1,.32,1),filter .8s}
.sbs-ab__art:hover .sbs-ab__photo img{transform:scale(1.07)}
.sbs-ab__art:hover .sbs-ab__frame{transform:translate(8px,8px)}
.sbs-ab__seal{position:absolute;top:34px;right:-8px;z-index:3;display:grid;place-items:center;width:124px;height:124px;border-radius:50%;background:var(--kr-primary);color:var(--kr-accent-light);box-shadow:0 18px 40px rgba(22,35,58,.3)}
.sbs-ab__seal-ring{position:absolute;inset:0;width:100%;height:100%;animation:sbs-spin 22s linear infinite}
.sbs-ab__seal text{font:600 9px var(--kr-font-body);fill:var(--kr-accent-light)}
@keyframes sbs-spin{to{transform:rotate(360deg)}}
.sbs-ab__float{position:absolute;left:-34px;bottom:64px;z-index:3;display:flex;flex-direction:column;gap:2px;padding:20px 26px;background:var(--kr-background);border-left:3px solid var(--kr-accent);box-shadow:0 24px 60px rgba(22,35,58,.22)}
.sbs-ab__float b{font:500 1.2rem/1.25 var(--kr-font-heading);letter-spacing:-.02em;color:var(--kr-primary)}
.sbs-ab__float span{margin-top:8px;font-size:13px;color:var(--kr-text-muted)}
/* reveal: only armed after mount, so the section is fully visible without JS */
.sbs-ab__art.is-armed:not(.is-in) .sbs-ab__photo{clip-path:inset(100% 0 0 0)}
.sbs-ab__art.is-armed:not(.is-in) .sbs-ab__frame{transform:translate(-28px,-28px);opacity:0}
.sbs-ab__art.is-armed .sbs-ab__seal,.sbs-ab__art.is-armed .sbs-ab__float{transition:opacity .9s ease 1.1s,transform .9s cubic-bezier(.23,1,.32,1) 1.1s}
.sbs-ab__art.is-armed:not(.is-in) .sbs-ab__seal{opacity:0;transform:scale(.6) rotate(-40deg)}
.sbs-ab__art.is-armed:not(.is-in) .sbs-ab__float{opacity:0;transform:translateY(26px)}
.sbs-ab__copy p{margin:0 0 18px;color:var(--kr-text-muted)}
.sbs-ab__copy .sbs-title{margin-bottom:28px}
.sbs-ab__copy p.sbs-ab__lead{font-size:19px;line-height:1.6;color:var(--kr-text)}
.sbs-ab__facts{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin:34px 0 0;padding:0;list-style:none;border-top:1px solid var(--kr-border);border-bottom:1px solid var(--kr-border)}
.sbs-ab__facts li{display:flex;flex-direction:column;gap:3px;padding:22px 20px 22px 0}
.sbs-ab__facts li+li{padding-left:22px;border-left:1px solid var(--kr-border)}
.sbs-ab__facts svg{color:var(--kr-accent-dark);margin-bottom:8px}
.sbs-ab__facts b{font:500 1.15rem/1.2 var(--kr-font-heading);letter-spacing:-.02em;color:var(--kr-primary)}
.sbs-ab__facts span{font-size:14px;line-height:1.45;color:var(--kr-text-muted)}
.sbs-ab__quote{position:relative;margin:36px 0 0;padding:6px 0 6px 28px;border-left:2px solid var(--kr-accent)}
.sbs-ab__quote svg{display:block;margin-bottom:10px;color:var(--kr-accent)}
.sbs-ab__copy .sbs-ab__quote p{margin:0;max-width:26em;font:500 clamp(1.3rem,2vw,1.65rem)/1.35 var(--kr-font-heading);letter-spacing:-.025em;color:var(--kr-primary)}
.sbs-ab__quote cite{display:block;margin-top:14px;font:400 14px var(--kr-font-body);font-style:normal;color:var(--kr-accent-dark)}
.sbs-ab__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:36px}
@media(max-width:900px){
 .sbs-ab__grid{grid-template-columns:1fr}
 .sbs-ab__art{width:min(100%,400px)}
 .sbs-ab__float{left:-8px}
 .sbs-ab__seal{right:0}
}
@media(max-width:560px){.sbs-ab__facts{grid-template-columns:1fr}.sbs-ab__facts li+li{padding-left:0;border-left:0;border-top:1px solid var(--kr-border)}}
@media(prefers-reduced-motion:reduce){.sbs-ab__seal-ring{animation:none}.sbs-ab__photo,.sbs-ab__frame,.sbs-ab__photo img{transition:none}}

/* stats: a gold hairline on top */
.sbs-stats{border-top:1px solid rgba(201,169,97,.45)}

/* communities: numbered rows that link into the listings search */
.sbs-cm{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(40px,7vw,110px);align-items:start}
.sbs-cm__intro{position:sticky;top:120px}
.sbs-cm__list{margin:0;padding:0;list-style:none;border-top:1px solid var(--kr-border)}
.sbs-cm__list a{display:flex;align-items:center;gap:clamp(16px,3vw,32px);padding:clamp(18px,2.4vw,28px) 0;border-bottom:1px solid var(--kr-border);color:var(--kr-primary);transition:background .35s}
.sbs-cm__num{width:2.2em;font-size:14px;color:var(--kr-accent-dark);font-variant-numeric:tabular-nums}
.sbs-cm__name{font:500 clamp(1.8rem,3.2vw,2.8rem)/1.1 var(--kr-font-heading);letter-spacing:-.035em;transition:transform .4s cubic-bezier(.23,1,.32,1)}
.sbs-cm__count{margin-left:auto;font-size:15px;color:var(--kr-text-muted)}
.sbs-cm__list svg{flex:none;color:var(--kr-text-muted);transition:transform .35s,color .35s}
.sbs-cm__list a:hover{background:linear-gradient(90deg,rgba(201,169,97,.12),transparent)}
.sbs-cm__list a:hover .sbs-cm__name{transform:translateX(14px)}
.sbs-cm__list a:hover svg{transform:translate(4px,-4px);color:var(--kr-accent-dark)}
@media(max-width:900px){.sbs-cm{grid-template-columns:1fr}.sbs-cm__intro{position:static}}
@media(max-width:480px){.sbs-cm__count{display:none}.sbs-cm__list svg{margin-left:auto}}

/* instagram tiles: hover veil */
.sbs-ig__over{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:rgba(22,35,58,.66);color:#fff;opacity:0;transition:opacity .35s}
.sbs-ig__over em{font:500 14px var(--kr-font-body);font-style:normal}
.sbs-ig a:hover .sbs-ig__over,.sbs-ig a:focus-visible .sbs-ig__over{opacity:1}

/* footer */
.sbs-footer{padding:88px 0 36px}
.sbs-footer__grid{grid-template-columns:1.5fr .8fr 1.1fr 1.3fr;gap:clamp(28px,4vw,56px)}
.sbs-footer__blurb{margin:18px 0 22px;max-width:320px;line-height:1.7}
.sbs-footer__social{display:inline-grid;place-items:center;width:44px;height:44px;border:1px solid rgba(255,255,255,.25);border-radius:50%;transition:background .3s,color .3s,border-color .3s}
.sbs-footer__social:hover{background:var(--kr-accent);border-color:var(--kr-accent);color:var(--kr-primary)}
.sbs-footer__towns{columns:2;column-gap:20px}
.sbs-footer__towns li{break-inside:avoid}
.sbs-footer li{padding:6px 0}
.sbs-legal__row{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px;font-size:14px;color:rgba(255,255,255,.75)}
.sbs-legal__eho{display:inline-flex;align-items:center;gap:8px}
.sbs-legal__top{color:var(--kr-accent-light)}
.sbs-legal p{margin:0}
@media(max-width:960px){.sbs-footer__grid{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.sbs-footer__grid{grid-template-columns:1fr}}
`;

export default css;
