import React from "react";

import Chrome from "../sajra/Chrome";
import { useCatalogue } from "../ppm/primitives/property/useCatalogue";

type Props = {
  children: React.ReactNode;
  /** True when the page opens with full-bleed photography: the header floats transparent over it. */
  heroLed?: boolean;
};

/**
 * The site shell. One header and one footer for every page, including the 404
 * and the legal pages, so nothing sits outside the Sold by Sajra design.
 */
export default function Layout({ children, heroLed }: Props) {
  const { error } = useCatalogue();
  return (
    <Chrome overlay={heroLed}>
      {error && (
        <p role="status" style={{ padding: "1rem", margin: 0, background: "#fff3cd", color: "#664d03" }}>
          {error}
        </p>
      )}
      {children}
    </Chrome>
  );
}
