// The tags every page needs for search and for sharing.
//
// One component rather than a block of <meta> in each page's Head, because
// these come in sets that have to agree: a title that differs from og:title,
// or an og:image with no twitter:image, is the kind of thing nobody notices
// until a link is pasted into Slack and comes out blank.
//
// ── why the URL is imported rather than queried ──────────────────────────
// Gatsby's Head API runs outside the page's React tree, so useStaticQuery is
// not available in it. The site URL therefore comes from config, which
// gatsby-config.ts reads too — one value, not two that can drift.

import React from "react";

import { SITE_URL } from "../ppm/config/profile--site-url";
import { BUSINESS_NAME } from "../ppm/config/profile--business-name";

export type SeoProps = {
  /** Already includes the business name where that reads naturally. */
  title: string;
  description: string;
  /** Path of this page, e.g. "/about/". Used for the canonical and og:url. */
  pathname?: string;
  /**
   * Absolute URL, or a path from the site root.
   *
   * Property pages pass their own photograph, which is a far better share
   * card than a logo. Everything else falls back to the brand image.
   */
  image?: string;
  type?: "website" | "article";
  /** Rendered inside Head alongside the tags, for anything page-specific. */
  children?: React.ReactNode;
};

/** The brand card: 1200x630, the ratio every platform crops from. */
const DEFAULT_IMAGE = "/og-image.png";

const absolute = (value: string): string =>
  /^https?:\/\//i.test(value) ? value : `${SITE_URL}${value.startsWith("/") ? "" : "/"}${value}`;

export default function Seo({
  title,
  description,
  pathname = "/",
  image,
  type = "website",
  children,
}: SeoProps) {
  const url = absolute(pathname);
  const card = absolute(image || DEFAULT_IMAGE);

  return (
    <>
      <title>{title}</title>
      <meta name="description" content={description} />
      <link rel="canonical" href={url} />

      {/* Open Graph: Facebook, LinkedIn, Slack, WhatsApp, iMessage. */}
      <meta property="og:type" content={type} />
      <meta property="og:site_name" content={BUSINESS_NAME} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={url} />
      <meta property="og:image" content={card} />
      {/* Stated explicitly: several platforms lay out the card before they
          have fetched the image, and without these the first render of a
          shared link jumps or falls back to a small thumbnail. */}
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:image:alt" content={title} />
      <meta property="og:locale" content="en_US" />

      {/* X reads its own namespace and ignores og:type. */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={card} />
      <meta name="twitter:image:alt" content={title} />

      {children}
    </>
  );
}
